export function EscalationQueue({
  queueName = "{{queueName}}",
  filter = "{{filter}}",
  accent = "{{accent}}",
  showAge = {{showAge}},
}) {
  const rows = [
    { id: "#4471 payment retry", sev: "medium", age: "2h", tag: { background: "#24143014" } },
    { id: "#4472 data mismatch", sev: "high", age: "6h", tag: { background: "#24143024" } },
    { id: "#4473 outage report", sev: "critical", age: "19h", tag: { background: accent, fontWeight: 700 }, border: accent },
  ];
  const order = { medium: 0, high: 1, critical: 2 };
  const min = { all: 0, high: 1, critical: 2 }[filter];
  return (
    <div style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 10px", fontWeight: 700 }}>{queueName}</p>
      {rows.filter((r) => order[r.sev] >= min).map((r) => (
        <div key={r.id} style={{ display: "flex", alignItems: "center", gap: 8, padding: 8, borderRadius: 6, background: "#ffffff", border: "1px solid #24143014", borderLeft: `3px solid ${r.border ?? "transparent"}`, marginBottom: 6 }}>
          {r.id}
          <span style={{ fontSize: 10, padding: "2px 7px", borderRadius: 999, ...r.tag }}>{r.sev}</span>
          {showAge && <small style={{ marginLeft: "auto", color: "#24143080", fontSize: 10 }}>{r.age}</small>}
        </div>
      ))}
    </div>
  );
}
